// Only post pages carry a tested-on box: one path segment, not a hub,
// an author page or one of the trust pages.
const xml = String($input.first().json.data || '');
const pages = new Set(['about', 'editorial-policy', 'affiliate-disclosure', 'privacy', 'contact']);
const urls = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)]
  .map((m) => m[1])
  .filter((u) => {
    const parts = new URL(u).pathname.split('/').filter(Boolean);
    return parts.length === 1 && !pages.has(parts[0]) && parts[0] !== 'topics';
  });
return urls.length ? urls.map((url) => ({ json: { url } })) : [{ json: { url: null } }];

/*
 * The tested-on date is rendered on the page, so this needs no repository
 * access and no credentials: a post is due 120 days after it was tested.
 */
const RETEST_DAYS = 120;
const now = Date.now();
const due = [];
const untested = [];

for (const item of $input.all()) {
  const html = String(item.json.body ?? '');
  const url = item.json.url ?? '';
  const m = html.match(/Tested on ([0-9]{1,2} [A-Za-z]+ [0-9]{4})/);
  if (!m) {
    if (/\/(how-to|fix|review)/.test(html)) untested.push(url);
    continue;
  }
  const tested = new Date(m[1]);
  if (Number.isNaN(tested.getTime())) continue;
  const days = Math.floor((now - tested.getTime()) / 86400000);
  if (days >= RETEST_DAYS) due.push({ url, tested: m[1], days, overdue: days - RETEST_DAYS });
}

due.sort((a, b) => b.overdue - a.overdue);

const lines = due.length
  ? [
      `${due.length} post(s) are due for re-testing.`,
      '',
      ...due.map((d) => `  ${String(d.overdue).padStart(4)}d overdue  tested ${d.tested}  ${d.url}`),
      '',
      'Re-test on current versions. If nothing changed, update testedOn.date and',
      'leave updatedAt alone. If the steps changed, update both.',
    ]
  : [];

return [{ json: { count: due.length, report: lines.join('\n'), checked: $input.all().length } }];
